function jbRes($code,$ok,$msg,$extra=array()){while(ob_get_level()>0){@ob_end_clean();}http_response_code((int)$code);echo json_encode(array_merge(array('success'=>(bool)$ok,'message'=>(string)$msg),$extra),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function jbP($k,$d=''){return isset($_POST[$k])?$_POST[$k]:$d;}
function jbCol(PDO $pdo,$t,$c){static $m=array();$k=$t.'.'.$c;if(isset($m[$k]))return $m[$k];$s=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c");$s->execute(array(':t'=>$t,':c'=>$c));return $m[$k]=(int)$s->fetchColumn()>0;}
function jbTable(PDO $pdo,$t){static $m=array();if(isset($m[$t]))return $m[$t];$s=$pdo->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t");$s->execute(array(':t'=>$t));return $m[$t]=(int)$s->fetchColumn()>0;}
function jbJob(PDO $pdo,$tenant,$id){$s=$pdo->prepare("SELECT * FROM jobs WHERE id=:id AND tenant_id=:t AND deleted_at IS NULL LIMIT 1");$s->execute(array(':id'=>$id,':t'=>$tenant));$r=$s->fetch();if(!$r)jbRes(404,false,'Job not found.');return $r;}
function jbAssignments(PDO $pdo,$tenant,$job){$s=$pdo->prepare("SELECT ja.*,CONCAT(u.first_name,CASE WHEN u.last_name IS NOT NULL AND u.last_name<>'' THEN CONCAT(' ',u.last_name) ELSE '' END) user_name,u.email,u.department_id FROM job_assignments ja LEFT JOIN users u ON u.id=ja.user_id AND u.tenant_id=ja.tenant_id WHERE ja.tenant_id=:t AND ja.job_id=:j AND ja.status<>'removed' ORDER BY ja.is_primary_responsible DESC,ja.id");$s->execute(array(':t'=>$tenant,':j'=>$job));return $s->fetchAll();}
function jbCurrency(PDO $pdo,$tenant){$s=$pdo->prepare("SELECT c.* FROM tenants t LEFT JOIN currencies c ON c.id=t.currency_id WHERE t.id=:t LIMIT 1");$s->execute(array(':t'=>$tenant));$r=$s->fetch();return $r?$r:array('symbol'=>'','symbol_position'=>'before','decimal_places'=>2,'currency_code'=>'');}
function jbDefaultWorkflow(PDO $pdo,$tenant,$service){if($service<=0)return null;$s=$pdo->prepare("SELECT w.id FROM service_workflows sw INNER JOIN workflows w ON w.id=sw.workflow_id AND w.tenant_id=:t AND w.status='active' INNER JOIN product_services ps ON ps.id=sw.product_service_id AND ps.tenant_id=:t2 WHERE sw.product_service_id=:s ORDER BY sw.is_default DESC,w.id DESC LIMIT 1");$s->execute(array(':t'=>$tenant,':t2'=>$tenant,':s'=>$service));$v=$s->fetchColumn();return $v?(int)$v:null;}
function jbNext(PDO $pdo,$tenant,$branch){$sep=jbCol($pdo,'document_sequences','number_separator')?'number_separator':'separator';$s=$pdo->prepare("SELECT ds.*,b.branch_code FROM document_sequences ds LEFT JOIN branches b ON b.id=ds.branch_id AND b.tenant_id=ds.tenant_id WHERE ds.tenant_id=:t AND ds.document_type='job' AND ds.is_active=1 AND (ds.branch_id=:b OR ds.branch_id IS NULL) ORDER BY CASE WHEN ds.branch_id=:b2 THEN 0 ELSE 1 END,ds.id LIMIT 1 FOR UPDATE");$s->execute(array(':t'=>$tenant,':b'=>$branch>0?$branch:0,':b2'=>$branch>0?$branch:0));$r=$s->fetch();if(!$r){$q=$pdo->prepare("SELECT MAX(CAST(SUBSTRING_INDEX(job_no,'-',-1) AS UNSIGNED)) FROM jobs WHERE tenant_id=:t AND job_no LIKE 'JOB-%'");$q->execute(array(':t'=>$tenant));return 'JOB-'.str_pad((string)((int)$q->fetchColumn()+1),6,'0',STR_PAD_LEFT);} $now=new DateTime('now');$y=$now->format('Y');$mo=$now->format('m');$fyStart=max(1,min(12,(int)$r['financial_year_start_month']));$fyY=(int)$now->format('n')>=$fyStart?(int)$y:(int)$y-1;$fy=$fyY.'-'.substr((string)($fyY+1),-2);$key='never';if($r['reset_period']==='monthly')$key=$y.$mo;elseif($r['reset_period']==='yearly')$key=$y;elseif($r['reset_period']==='financial_year')$key=$fy;$cur=(int)$r['current_number'];if($r['reset_period']!=='never'&&(string)$r['last_reset_key']!==(string)$key)$cur=0;$n=$cur+1;$mid='';if($r['middle_format']==='year')$mid=$y;elseif($r['middle_format']==='year_month')$mid=$y.$mo;elseif($r['middle_format']==='financial_year')$mid=$fy;elseif($r['middle_format']==='branch_year')$mid=(!empty($r['branch_code'])?$r['branch_code']:'BR').$y;$parts=array();if(!empty($r['prefix']))$parts[]=$r['prefix'];if($mid!=='')$parts[]=$mid;$parts[]=str_pad((string)$n,max(1,(int)$r['number_length']),'0',STR_PAD_LEFT);if(!empty($r['suffix']))$parts[]=$r['suffix'];$no=implode(isset($r[$sep])?(string)$r[$sep]:'-',$parts);$u=$pdo->prepare("UPDATE document_sequences SET current_number=:n,last_reset_key=:k WHERE id=:id");$u->execute(array(':n'=>$n,':k'=>$key,':id'=>$r['id']));return $no;}
function jbMeta(PDO $pdo,$tenant,$jobId=0){$m=array();$q=$pdo->prepare("SELECT q.id,q.quote_no,q.title,q.client_id,q.location_id,q.request_id,q.branch_id,q.subtotal,q.tax_total,q.total,c.display_name client_name,r.product_service_id,ps.name service_name FROM quotes q INNER JOIN clients c ON c.id=q.client_id AND c.tenant_id=q.tenant_id LEFT JOIN service_requests r ON r.id=q.request_id AND r.tenant_id=q.tenant_id LEFT JOIN product_services ps ON ps.id=r.product_service_id AND ps.tenant_id=q.tenant_id WHERE q.tenant_id=:t AND (q.status='approved' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=:jid AND j.tenant_id=q.tenant_id AND j.quote_id=q.id)) AND (NOT EXISTS(SELECT 1 FROM jobs j2 WHERE j2.tenant_id=q.tenant_id AND j2.quote_id=q.id AND j2.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM jobs j3 WHERE j3.id=:jid2 AND j3.tenant_id=q.tenant_id AND j3.quote_id=q.id)) ORDER BY q.id DESC");$q->execute(array(':t'=>$tenant,':jid'=>$jobId,':jid2'=>$jobId));$m['quotes']=$q->fetchAll();$s=$pdo->prepare("SELECT id,CONCAT(first_name,CASE WHEN last_name IS NOT NULL AND last_name<>'' THEN CONCAT(' ',last_name) ELSE '' END) name,email,department_id,job_title,is_field_worker FROM users WHERE tenant_id=:t AND status='active' AND deleted_at IS NULL AND (is_bookable=1 OR is_field_worker=1 OR is_tenant_admin=1) ORDER BY first_name,last_name");$s->execute(array(':t'=>$tenant));$m['users']=$s->fetchAll();$s=$pdo->prepare("SELECT id,name,branch_id FROM departments WHERE tenant_id=:t AND status='active' ORDER BY name");$s->execute(array(':t'=>$tenant));$m['departments']=$s->fetchAll();$s=$pdo->prepare("SELECT id,name FROM branches WHERE tenant_id=:t AND status='active' ORDER BY is_head_office DESC,name");$s->execute(array(':t'=>$tenant));$m['branches']=$s->fetchAll();$m['currency']=jbCurrency($pdo,$tenant);return $m;}
function jbQuote(PDO $pdo,$tenant,$id,$jobId=0){$s=$pdo->prepare("SELECT q.*,c.display_name client_name,r.product_service_id,r.title request_title,r.description request_description,ps.name service_name FROM quotes q INNER JOIN clients c ON c.id=q.client_id AND c.tenant_id=q.tenant_id LEFT JOIN service_requests r ON r.id=q.request_id AND r.tenant_id=q.tenant_id LEFT JOIN product_services ps ON ps.id=r.product_service_id AND ps.tenant_id=q.tenant_id WHERE q.id=:id AND q.tenant_id=:t AND (q.status='approved' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=:jid AND j.tenant_id=q.tenant_id AND j.quote_id=q.id)) LIMIT 1");$s->execute(array(':id'=>$id,':t'=>$tenant,':jid'=>$jobId));$r=$s->fetch();if(!$r)jbRes(422,false,'Select a valid approved quotation.');$r['workflow_id']=jbDefaultWorkflow($pdo,$tenant,(int)$r['product_service_id']);return $r;}

function jbInitWorkflow(PDO $pdo,$tenant,$job,$workflow,$primaryUser){
    if($workflow<=0||!jbTable($pdo,'job_workflow_progress'))return;
    $q=$pdo->prepare("SELECT id FROM workflow_steps WHERE workflow_id=:w ORDER BY sort_order,id");
    $q->execute(array(':w'=>$workflow));$steps=$q->fetchAll(PDO::FETCH_COLUMN);if(!$steps)return;
    $check=$pdo->prepare("SELECT id,status FROM job_workflow_progress WHERE tenant_id=:t AND job_id=:j AND visit_id IS NULL AND workflow_step_id=:s ORDER BY id LIMIT 1");
    $ins=$pdo->prepare("INSERT INTO job_workflow_progress(tenant_id,job_id,visit_id,workflow_step_id,assigned_user_id,assigned_team_id,status) VALUES(:t,:j,NULL,:s,:u,NULL,:st)");
    $upd=$pdo->prepare("UPDATE job_workflow_progress SET assigned_user_id=:u WHERE id=:id AND status IN('pending','available')");
    foreach($steps as $i=>$sid){$check->execute(array(':t'=>$tenant,':j'=>$job,':s'=>$sid));$r=$check->fetch();if(!$r)$ins->execute(array(':t'=>$tenant,':j'=>$job,':s'=>$sid,':u'=>$primaryUser>0?$primaryUser:null,':st'=>$i===0?'available':'pending'));else $upd->execute(array(':u'=>$primaryUser>0?$primaryUser:null,':id'=>$r['id']));}
}
function jbActivity(PDO $pdo,$tenant,$branch,$user,$type,$job,$client,$title,$details){try{$s=$pdo->prepare("INSERT INTO activity_events(tenant_id,branch_id,actor_user_id,actor_type,event_type,related_type,related_id,client_id,title,details_json,visible_to_client) VALUES(:t,:b,:u,'user',:e,'job',:rid,:cid,:title,:d,0)");$s->execute(array(':t'=>$tenant,':b'=>$branch>0?$branch:null,':u'=>$user,':e'=>$type,':rid'=>$job,':cid'=>$client,':title'=>substr($title,0,255),':d'=>json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)));}catch(Throwable $e){error_log('job activity '.$e->getMessage());}}
function jbDecrypt($encrypted,$tenant){$encrypted=trim((string)$encrypted);if($encrypted==='')return '';$raw=base64_decode($encrypted,true);if($raw===false||strlen($raw)<=16)throw new RuntimeException('Stored SMTP password is invalid.');$env=getenv('FIELDPLX_APP_KEY');$seed=($env===false||trim($env)==='')?((defined('DB_NAME')?DB_NAME:'').'|'.(defined('DB_USER')?DB_USER:'').'|'.(defined('DB_PASS')?DB_PASS:'').'|'.$tenant):($env.'|'.$tenant);$key=hash('sha256',$seed,true);$plain=openssl_decrypt(substr($raw,16),'AES-256-CBC',$key,OPENSSL_RAW_DATA,substr($raw,0,16));if($plain===false)throw new RuntimeException('Unable to decrypt SMTP password.');return $plain;}
function jbSmtpRead($s){$r='';while(!feof($s)){$l=fgets($s,515);if($l===false)break;$r.=$l;if(strlen($l)>=4&&$l[3]===' ')break;}return trim($r);}
function jbSmtpCmd($s,$cmd,$ok,$label){if($cmd!==null&&@fwrite($s,$cmd."\r\n")===false)throw new RuntimeException('SMTP connection closed during '.$label.'.');$r=jbSmtpRead($s);$c=(int)substr($r,0,3);if(!in_array($c,(array)$ok,true))throw new RuntimeException($label.' failed (SMTP '.$c.'): '.substr(preg_replace('/[\r\n]+/',' ',$r),0,220));return $r;}
function jbSmtpConfig(PDO $pdo,$tenant,$branch){if(!jbTable($pdo,'smtp_configurations'))return null;$q=$pdo->prepare("SELECT * FROM smtp_configurations WHERE tenant_id=:t AND is_active=1 AND scope_type IN('tenant','branch') AND (scope_type='tenant' OR (scope_type='branch' AND branch_id=:b)) ORDER BY CASE WHEN scope_type='branch' AND branch_id=:b2 THEN 0 ELSE 1 END,is_default DESC,id DESC LIMIT 1");$q->execute(array(':t'=>$tenant,':b'=>$branch>0?$branch:-1,':b2'=>$branch>0?$branch:-1));$r=$q->fetch();return $r?$r:null;}
function jbMail($cfg,$password,$to,$subject,$html){if(!filter_var($to,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Assignee email is invalid.');$host=trim($cfg['host']);$port=(int)$cfg['port'];$enc=strtolower(trim($cfg['encryption']));$user=trim((string)$cfg['username']);$from=trim((string)$cfg['from_email']);if(!filter_var($from,FILTER_VALIDATE_EMAIL))throw new RuntimeException('SMTP From Email is invalid.');$remote=($enc==='ssl'?'ssl://':'tcp://').$host.':'.$port;$ctx=stream_context_create(array('ssl'=>array('verify_peer'=>true,'verify_peer_name'=>true,'allow_self_signed'=>false,'peer_name'=>$host)));$errno=0;$err='';$s=@stream_socket_client($remote,$errno,$err,20,STREAM_CLIENT_CONNECT,$ctx);if(!$s)throw new RuntimeException('Unable to connect to SMTP server: '.($err!==''?$err:'connection failed'));stream_set_timeout($s,20);try{jbSmtpCmd($s,null,array(220),'SMTP greeting');$eh='fieldplx.local';jbSmtpCmd($s,'EHLO '.$eh,array(250),'EHLO');if($enc==='tls'||$enc==='starttls'){jbSmtpCmd($s,'STARTTLS',array(220),'STARTTLS');$method=defined('STREAM_CRYPTO_METHOD_TLS_CLIENT')?STREAM_CRYPTO_METHOD_TLS_CLIENT:STREAM_CRYPTO_METHOD_SSLv23_CLIENT;if(@stream_socket_enable_crypto($s,true,$method)!==true)throw new RuntimeException('Unable to establish TLS encryption.');jbSmtpCmd($s,'EHLO '.$eh,array(250),'EHLO after TLS');}if($user!==''){jbSmtpCmd($s,'AUTH LOGIN',array(334),'SMTP authentication');jbSmtpCmd($s,base64_encode($user),array(334),'SMTP username');jbSmtpCmd($s,base64_encode($password),array(235),'SMTP password');}jbSmtpCmd($s,'MAIL FROM:<'.$from.'>',array(250),'MAIL FROM');jbSmtpCmd($s,'RCPT TO:<'.$to.'>',array(250,251),'RCPT TO');jbSmtpCmd($s,'DATA',array(354),'DATA');$fromName=trim((string)$cfg['from_name']);$headers=array('Date: '.date(DATE_RFC2822),'From: '.($fromName!==''?$fromName:'FieldPlx').' <'.$from.'>','To: <'.$to.'>','Subject: '.str_replace(array("\r","\n"),' ',$subject),'MIME-Version: 1.0','Content-Type: text/html; charset=UTF-8');$payload=implode("\r\n",$headers)."\r\n\r\n".$html;$payload=preg_replace('/(?m)^\./','..',$payload);@fwrite($s,$payload."\r\n.\r\n");jbSmtpCmd($s,null,array(250),'Message delivery');@fwrite($s,"QUIT\r\n");}finally{@fclose($s);}return true;}
